-- Testes reais, sem persistência de concessões, dados ou auditoria.
begin;
set local statement_timeout='30s';
set local lock_timeout='3s';
set local plpgsql.check_asserts=on;
set local role authenticated;
do $test$
declare admin_id uuid;employee_id uuid;cash_id uuid;row_id uuid:=gen_random_uuid();r jsonb;baseline jsonb;bad boolean;begin
 select id into admin_id from public.profiles where coalesce(is_master,false)or role in('master','diretor','diretoria')order by is_master desc limit 1;
 select id into employee_id from public.profiles where lower(full_name)='vitor amaral';
 if admin_id is null or employee_id is null then raise exception 'Perfis de teste ausentes.';end if;
 perform set_config('request.jwt.claim.sub',employee_id::text,true);
 baseline:=public.pdi_module_access_context();
 begin perform public.pdi_performance_access_admin_context();raise exception 'Funcionário acessou administração';exception when insufficient_privilege then null;end;
 begin perform public.pdi_set_performance_access(employee_id,'pcp_m2','collect',null,'Teste de autoatribuição negada');raise exception 'Funcionário atribuiu acesso';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 assert jsonb_array_length(public.pdi_performance_access_admin_context()->'modules')=6,'Seis módulos';
 begin perform public.pdi_set_performance_access(admin_id,'pcp_m2','blocked',null,'Tentativa de bloquear administração');raise exception 'Bloqueou diretoria';exception when invalid_parameter_value then null;end;
 begin perform public.pdi_set_performance_access(employee_id,'pcp_m2','supervisor',null,'Tentativa de trocar a supervisão do PCP');raise exception 'Supervisor PCP fora do Rodrigo';exception when invalid_parameter_value then null;end;
 r:=public.pdi_set_performance_access(employee_id,'pcp_m2','collect',null,'Teste de concessão temporária de PCP');assert (r->>'revision')::int=1;
 begin perform public.pdi_set_performance_access(employee_id,'pcp_m2','view',null,'Teste de conflito de revisão');raise exception 'Aceitou revisão obsoleta';exception when serialization_failure then null;end;
 perform set_config('request.jwt.claim.sub',employee_id::text,true);
 assert pdi_performance_private.can_collect_module('pcp_m2');assert not pdi_performance_private.can_view_module('pcp_m2');assert(public.pdi_desempenho_context()->>'is_pcp')::boolean;
 insert into public.pdi_pcp_daily(id,pcp_id,work_date,m2_saved,m2_analyzed,order_numbers)values(row_id,employee_id,pdi_performance_private.today_manaus(),1,10,array['999000001']);
 assert exists(select 1 from public.pdi_pcp_daily where id=row_id),'Coletor enxerga próprio registro';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 r:=public.pdi_set_performance_access(employee_id,'pcp_m2','blocked',1,'Teste de bloqueio temporário do PCP');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);
 assert not pdi_performance_private.can_collect_module('pcp_m2');assert not pdi_performance_private.can_view_module('pcp_m2');
 assert not exists(select 1 from public.pdi_pcp_daily where id=row_id),'Bloqueio impede ler até registro próprio';
 begin perform public.pdi_pcp_dashboard('2020-01-01','2020-01-03',null);raise exception 'RPC ignorou bloqueio';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'pcp_m2','view',2,'Teste de consulta sem lançamento');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);
 assert pdi_performance_private.can_view_module('pcp_m2');assert not pdi_performance_private.can_collect_module('pcp_m2');assert exists(select 1 from public.pdi_pcp_daily where id=row_id);
 begin insert into public.pdi_pcp_daily(pcp_id,work_date,m2_saved,m2_analyzed,order_numbers)values(employee_id,pdi_performance_private.today_manaus(),1,10,array['999000002']);raise exception 'Consulta escreveu no PCP';exception when insufficient_privilege then null;end;
 begin perform public.pdi_delete_performance('pcp_m2','records',row_id,'Tentativa de exclusão em consulta');raise exception 'Consulta chamou exclusão';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'pcp_m2',null,3,'Teste de restauração do padrão');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert public.pdi_module_access_context()=baseline,'Restaurar preserva autorização anterior';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'cash_daily','collect',null,'Teste de caixa por autorização explícita');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert(public.pdi_cash_context()->>'is_cashier')::boolean;assert pdi_performance_private.can_collect_module('cash_daily');insert into public.pdi_cash_daily(cashier_id,result_cents)values(employee_id,0);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'sales_campaign','collect',null,'Teste de vendedor por autorização explícita');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert(public.pdi_sales_context()->>'allowed')::boolean;assert(public.pdi_sales_context()->>'is_participant')::boolean;assert not(public.pdi_sales_context()->>'can_manage')::boolean;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'sales_campaign','blocked',1,'Teste de retirada do acesso comercial');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert not(public.pdi_sales_context()->>'allowed')::boolean;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'erika_glass','production',null,'Teste de produção E.G. por autorização explícita');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);r:=public.pdi_eg_context();assert(r->>'can_production')::boolean;assert not(r->>'can_finance')::boolean;assert not(r->>'can_stock')::boolean;assert not(r->>'can_delete')::boolean;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'erika_glass','blocked',1,'Teste de retirada do E.G.');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert not(public.pdi_eg_context()->>'allowed')::boolean;
 begin perform public.pdi_eg_export_log('records',0,'{}');raise exception 'E.G. bloqueado chamou RPC';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'stock','blocked',null,'Teste de retirada de estoque');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert not pdi_performance_private.stock_operator();
 begin perform public.pdi_stock_context();raise exception 'Estoque ignorou bloqueio';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'logistics','collect',null,'Teste de operação logística explícita');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert pdi_performance_private.can_collect_module('logistics');assert pdi_performance_private.logistics_read();assert not pdi_performance_private.logistics_register();
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.pdi_set_performance_access(employee_id,'logistics','blocked',1,'Teste de retirada de logística');
 perform set_config('request.jwt.claim.sub',employee_id::text,true);assert not pdi_performance_private.logistics_read();
 begin perform public.pdi_logistics_context();raise exception 'Logística ignorou bloqueio';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 assert exists(select 1 from public.pdi_area_access_audit where actor_id=admin_id and action='PERFORMANCE_BLOCK'and after_data->>'profile_id'=employee_id::text and after_data->>'reason'is not null),'Alterações auditadas com motivo';
 assert not has_function_privilege('anon','public.pdi_set_performance_access(uuid,text,text,integer,text)','execute');
 assert not has_table_privilege('authenticated','public.pdi_performance_access','insert');
end$test$;
select 'PASS: autorizações, isolamento, bloqueio RPC/RLS, consulta, concessão, restauração, revisão e auditoria' resultado;
rollback;
